mapper.select:
select cc.course_id
from course_choice cc
where user_id = #{studentId}

select id as course_choice_id, user_id as student_id, course_id
from course_choice
where id = #{courseChoiceId}

select c.id as course_id, c.course_no, c.course_name, c.user_id as teacher_no, u.name as teacher_name from course c left join user u on c.user_id = u.id
AND c.course_name LIKE CONCAT('%',#{courseName},'%')
order by c.id desc limit #{offset}, #{pageSize}
